const STORE={students:'kkStudentManager.students',attendance:'kkStudentManager.attendance',results:'kkInstitute.results',library:'kkInstitute.library',fees:'kkInstitute.fees',notices:'kkInstitute.notices',staff:'kkInstitute.staff',timetable:'kkInstitute.timetable',settings:'kkInstitute.settings',accounts:'kkInstitute.accounts',staffAttendance:'kkInstitute.staffAttendance'};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function read(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v??fallback}catch{return fallback}}
function write(key,value){localStorage.setItem(key,JSON.stringify(value))}
let students=read(STORE.students,[]),attendance=read(STORE.attendance,{}),staffAttendance=read(STORE.staffAttendance,{}),results=read(STORE.results,[]),library=read(STORE.library,[]),fees=read(STORE.fees,[]),notices=read(STORE.notices,[]),staff=read(STORE.staff,[]),timetable=read(STORE.timetable,[]),settings=read(STORE.settings,{org:'KK EduTech Solutions',title:'KK Institute Suite',year:'2026–2027',threshold:75,dark:false}),accounts=read(STORE.accounts,{}),
companies=read('kkInstitute.tpo.companies',[]),
jobs=read('kkInstitute.tpo.jobs',[]),
applications=read('kkInstitute.tpo.applications',[]),
interviews=read('kkInstitute.tpo.interviews',[]),
offers=read('kkInstitute.tpo.offers',[]),
training=read('kkInstitute.tpo.training',[]);
let session=null,currentPage='dashboard',toastTimer=null,modalHandler=null;
const pageMeta={'tpo-dashboard':['TPO Dashboard','Placement overview, recruitment drives, and student outcomes'],companies:['Company Directory','Manage recruiting companies and HR contacts'],jobs:['Jobs & Internships','Browse opportunities and manage recruitment listings'],applications:['Placement Applications','Review student applications and application status'],interviews:['Interview Schedule','Schedule and track placement interviews'],offers:['Placement Offers','Track offers, packages, and student placement outcomes'],training:['Placement Training','Manage employability training and mock interviews'],'placement-analytics':['Placement Analytics','Review placement performance and recruitment outcomes'],profile:['My Profile','Personal and account information'],dashboard:['Dashboard','Institute overview at a glance'],students:['Student Directory','Manage student records and class information'],attendance:['Attendance Management','Record, review, and monitor daily attendance'],results:['Exams & Results','Manage assessments and published results'],library:['Digital Library','Learning resources, notes, papers, and references'],fees:['Fees & Payments','Track student fee records and payment status'],timetable:['Timetable','Weekly academic schedule and class sessions'],notices:['Notice Board','Announcements and important institute updates'],staff:['Faculty & Staff','Manage faculty and administrative contacts'],'staff-attendance':['Staff Attendance','Track daily attendance for faculty and staff'],reports:['Reports & Analytics','Institute performance and academic summaries'],settings:['Institute Settings','Configure institute identity and workspace preferences']};
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);const today=()=>new Date().toISOString().slice(0,10);const monthNow=()=>today().slice(0,7);const initials=n=>String(n||'?').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();const fmtDate=d=>d?new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';const monthName=m=>m?new Date(m+'-01T00:00:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'}):'—';
function saveAll(){write('kkInstitute.tpo.companies',companies);write('kkInstitute.tpo.jobs',jobs);write('kkInstitute.tpo.applications',applications);write('kkInstitute.tpo.interviews',interviews);write('kkInstitute.tpo.offers',offers);write('kkInstitute.tpo.training',training);write(STORE.students,students);write(STORE.attendance,attendance);write(STORE.staffAttendance,staffAttendance);write(STORE.results,results);write(STORE.library,library);write(STORE.fees,fees);write(STORE.notices,notices);write(STORE.staff,staff);write(STORE.timetable,timetable);write(STORE.settings,settings);write(STORE.accounts,accounts);}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function statusBadge(text,cls='neutral'){return `<span class="status status-${cls}">${escapeHTML(text)}</span>`}
function button(label,action,kind='ghost',small=true){return `<button class="btn ${kind==='primary'?'btn-primary':kind==='danger'?'btn-danger':kind==='secondary'?'btn-secondary':'btn-ghost'} ${small?'btn-small':''}" data-action="${escapeHTML(action)}">${label}</button>`}
function emptyState(icon,title,desc,action=''){return `<div class="empty-state"><div class="empty-icon">${icon}</div><b>${escapeHTML(title)}</b><p>${escapeHTML(desc)}</p>${action}</div>`}
function pageHeading(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function studentName(id){return students.find(s=>String(s.id)===String(id))?.name||'Unknown student'}
function allAttendanceRecords(){return Object.values(attendance).filter(r=>r&&r.date&&r.students)}
function attendanceStats(records=allAttendanceRecords()) {let p=0,a=0,l=0,marked=0;records.forEach(r=>Object.values(r.students||{}).forEach(s=>{if(['Present','Absent','Late'].includes(s)){marked++;if(s==='Present')p++;if(s==='Absent')a++;if(s==='Late')l++}}));return {p,a,l,marked,rate:marked?Math.round((p+l)/marked*100):0}}
function studentAttendance(id,month=''){const recs=allAttendanceRecords().filter(r=>(!month||r.date.startsWith(month))&&r.students&&r.students[id]);const c={Present:0,Absent:0,Late:0};recs.forEach(r=>{if(c[r.students[id]]!==undefined)c[r.students[id]]++});const marked=c.Present+c.Absent+c.Late;return {...c,marked,rate:marked?Math.round((c.Present+c.Late)/marked*100):null}}
function monthRecords(month=monthNow(),cls=''){return allAttendanceRecords().filter(r=>r.date.startsWith(month)&&(!cls||r.className===cls))}
function summaryCard(label,value,icon,color='green',foot='') {return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ico-${color}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`}
function initialsCell(s){return `<div class="student-cell"><span class="student-avatar">${escapeHTML(initials(s.name))}</span><span><b>${escapeHTML(s.name)}</b><small>${escapeHTML(s.email||s.id||'Student')}</small></span></div>`}
function openModal(title,body,onSave,eyebrow='MANAGEMENT'){ $('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=body;modalHandler=onSave;const dlg=$('#modalDialog');if(!dlg.open)dlg.showModal(); }
$('#modalForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();if(modalHandler&&modalHandler()!==false){$('#modalDialog').close();modalHandler=null}});
function field(label,name,value='',type='text',placeholder='',required=false,options=null){let control;if(options){control=`<select name="${name}" ${required?'required':''}>${options.map(o=>`<option value="${escapeHTML(o.value)}" ${String(o.value)===String(value)?'selected':''}>${escapeHTML(o.label)}</option>`).join('')}</select>`}else if(type==='textarea'){control=`<textarea name="${name}" placeholder="${escapeHTML(placeholder)}" ${required?'required':''}>${escapeHTML(value)}</textarea>`}else{control=`<input name="${name}" type="${type}" value="${escapeHTML(value)}" placeholder="${escapeHTML(placeholder)}" ${required?'required':''}>`}return `<div class="field"><label>${label}${required?' *':''}</label>${control}</div>`}
function formGrid(fields){return `<div class="field-grid">${fields.join('')}</div>`}
function formVal(name){return $('#modalBody [name="'+name+'"]')?.value?.trim()||''}

function tpoTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="muted">No records yet.</td></tr>`}</tbody></table></div>`}
function tpoStat(label,value,sub,icon='▥'){return `<article class="tpo-stat"><div class="tpo-stat-icon">${icon}</div><span>${escapeHTML(label)}</span><strong>${value}</strong><small>${escapeHTML(sub)}</small></article>`}
function renderTpoDashboard(){
 const placed=new Set(offers.filter(o=>o.status!=='Declined').map(o=>String(o.studentId))).size;
 const activeJobs=jobs.filter(j=>j.status==='Open').length;
 const pending=applications.filter(a=>['Applied','Under Review','Shortlisted'].includes(a.status)).length;
 const avg=offers.length?Math.round(offers.reduce((n,o)=>n+Number(o.package||0),0)/offers.length*100)/100:0;
 return `${pageHeading('TPO Dashboard','Training and Placement Office overview for recruitment and student outcomes.',button('Add company','add-company','primary')+button('Post job','add-job','secondary'))}
 <section class="tpo-hero"><div><p class="eyebrow">PLACEMENT OPERATIONS</p><h2>Build careers. Connect talent. Track outcomes.</h2><p>Manage employers, opportunities, applications, interviews, offers, and student readiness in one workspace.</p></div><div class="tpo-hero-mark">KK<br><small>TPO</small></div></section>
 <div class="tpo-stats">${tpoStat('Recruiting companies',companies.length,'Registered employers','▦')}${tpoStat('Open opportunities',activeJobs,'Jobs and internships','⌕')}${tpoStat('Applications',applications.length,`${pending} in progress`,'☷')}${tpoStat('Students placed',placed,`${offers.length} offer records`,'✓')}</div>
 <div class="grid two-col"><section class="panel"><div class="panel-heading"><div><h3>Recent Opportunities</h3><p>Latest job and internship listings</p></div>${button('View all jobs','go-jobs')}</div>${tpoTable(['Role','Company','Package','Deadline','Status'],jobs.slice(-5).reverse().map(j=>`<tr><td><b>${escapeHTML(j.title)}</b><small class="table-sub">${escapeHTML(j.location||'Location not specified')}</small></td><td>${escapeHTML(companyName(j.companyId))}</td><td>${escapeHTML(j.package||'Not specified')}</td><td>${escapeHTML(j.deadline||'—')}</td><td>${statusBadge(j.status||'Open',(j.status||'Open')==='Open'?'active':'neutral')}</td></tr>`).join(''))}</section>
 <section class="panel"><div class="panel-heading"><div><h3>Application Pipeline</h3><p>Current candidate progress</p></div></div><div class="pipeline-list">${['Applied','Under Review','Shortlisted','Interview','Selected','Rejected'].map(st=>{const n=applications.filter(a=>a.status===st).length;return `<div class="pipeline-row"><span>${st}</span><div class="pipeline-track"><i style="width:${applications.length?Math.max(n?5:0,n/applications.length*100):0}%"></i></div><b>${n}</b></div>`}).join('')}</div></section></div>
 <section class="panel"><div class="panel-heading"><div><h3>Upcoming Interviews</h3><p>Scheduled interview rounds</p></div>${button('Manage interviews','go-interviews')}</div>${tpoTable(['Student','Company / Role','Date','Mode','Status'],interviews.filter(i=>i.status!=='Completed').slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')).slice(0,6).map(i=>`<tr><td>${escapeHTML(studentName(i.studentId))}</td><td>${escapeHTML(companyName(i.companyId))} / ${escapeHTML(i.role||'Interview')}</td><td>${escapeHTML(i.date||'—')} ${escapeHTML(i.time||'')}</td><td>${escapeHTML(i.mode||'—')}</td><td>${statusBadge(i.status||'Scheduled','active')}</td></tr>`).join(''))}</section>`;
}
function companyName(id){return companies.find(c=>String(c.id)===String(id))?.name||'Company not set'}
function jobName(id){return jobs.find(j=>String(j.id)===String(id))?.title||'Opportunity'}
function renderCompanies(){if(session.role!=='admin')return `<section class="panel"><h2>Administrator access required</h2></section>`;return `${pageHeading('Company Directory','Manage employers, recruiters, and campus hiring relationships.',button('Add company','add-company','primary')+button('Export CSV','export-companies'))}<div class="tpo-stats">${tpoStat('Total companies',companies.length,'Employer profiles')}${tpoStat('Active recruiters',companies.filter(c=>c.status==='Active').length,'Available for hiring')}</div><section class="panel">${tpoTable(['Company','Industry','HR Contact','Email','Website','Status','Actions'],companies.map(c=>`<tr><td><b>${escapeHTML(c.name)}</b></td><td>${escapeHTML(c.industry||'—')}</td><td>${escapeHTML(c.hr||'—')}</td><td>${escapeHTML(c.email||'—')}</td><td>${c.website?`<a href="${escapeHTML(c.website)}" target="_blank" rel="noopener">Visit ↗</a>`:'—'}</td><td>${statusBadge(c.status||'Active','active')}</td><td>${button('Edit','edit-company:'+c.id,'secondary')}${button('Delete','delete-company:'+c.id,'danger')}</td></tr>`).join(''))}</section>`}
function renderJobs(){const admin=session.role==='admin';const visible=jobs.filter(j=>admin||j.status==='Open');return `${pageHeading(admin?'Jobs & Internships':'Career Opportunities',admin?'Publish opportunities and define student eligibility.':'Explore opportunities and apply using your student account.',admin?button('Post opportunity','add-job','primary'):'')}<div class="tpo-stats">${tpoStat('Available opportunities',visible.filter(j=>j.status==='Open').length,'Currently open','⌕')}${tpoStat('Internships',visible.filter(j=>/intern/i.test(j.type||'')).length,'Learning opportunities','✦')}${tpoStat('My applications',applications.filter(a=>admin||String(a.studentId)===String(session.student?.id)).length,'Application records','☷')}</div><section class="panel"><div class="panel-heading"><div><h3>${admin?'Opportunity Listings':'Open Opportunities'}</h3><p>Check role, eligibility, package, and deadline before applying.</p></div>${admin?button('Export CSV','export-jobs'):''}</div>${tpoTable(['Role / Opportunity','Company','Type','Eligibility','Package','Deadline','Status','Action'],visible.slice().reverse().map(j=>`<tr><td><b>${escapeHTML(j.title)}</b><small class="table-sub">${escapeHTML(j.location||'')}</small></td><td>${escapeHTML(companyName(j.companyId))}</td><td>${escapeHTML(j.type||'Full-time')}</td><td>${escapeHTML(j.eligibility||'Open to registered students')}</td><td>${escapeHTML(j.package||'Not specified')}</td><td>${escapeHTML(j.deadline||'—')}</td><td>${statusBadge(j.status||'Open',(j.status||'Open')==='Open'?'active':'neutral')}</td><td>${admin?button('Edit','edit-job:'+j.id,'secondary')+button('Close','close-job:'+j.id,'danger'):((applications.some(a=>a.jobId===j.id&&String(a.studentId)===String(session.student?.id)))?statusBadge('Applied','active'):button('Apply','apply-job:'+j.id,'primary'))}</td></tr>`).join(''))}</section>`}
function renderApplications(){const admin=session.role==='admin';const rows=applications.filter(a=>admin||String(a.studentId)===String(session.student?.id));return `${pageHeading('Placement Applications',admin?'Review candidate applications and update recruitment progress.':'Track your applications and recruitment status.',button('Export CSV','export-applications','secondary'))}<div class="tpo-stats">${tpoStat('Total applications',rows.length,'Visible records','☷')}${tpoStat('Shortlisted',rows.filter(a=>a.status==='Shortlisted').length,'Progressing candidates','✓')}${tpoStat('Selected',rows.filter(a=>a.status==='Selected').length,'Selected candidates','★')}</div><section class="panel">${tpoTable(['Student','Opportunity','Company','Applied on','Resume','Status','Action'],rows.slice().reverse().map(a=>`<tr><td><b>${escapeHTML(studentName(a.studentId))}</b><small class="table-sub">${escapeHTML(a.studentId)}</small></td><td>${escapeHTML(jobName(a.jobId))}</td><td>${escapeHTML(companyName(jobs.find(j=>j.id===a.jobId)?.companyId))}</td><td>${escapeHTML(a.appliedOn||'—')}</td><td>${a.resume?`<a href="${escapeHTML(a.resume)}" target="_blank" rel="noopener">Open ↗</a>`:escapeHTML(a.resumeName||'Not attached')}</td><td>${statusBadge(a.status||'Applied','active')}</td><td>${admin?button('Update status','status-application:'+a.id,'secondary'):'—'}</td></tr>`).join(''))}</section>`}
function renderInterviews(){const admin=session.role==='admin';const rows=interviews.filter(i=>admin||String(i.studentId)===String(session.student?.id));return `${pageHeading('Interview Schedule',admin?'Schedule interviews and record round outcomes.':'Review your upcoming interviews and selection rounds.',admin?button('Schedule interview','add-interview','primary'):'')}<section class="panel">${tpoTable(['Student','Company','Role / Round','Date','Time','Mode','Venue / Link','Status',...(admin?['Action']:[])],rows.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(i=>`<tr><td>${escapeHTML(studentName(i.studentId))}</td><td>${escapeHTML(companyName(i.companyId))}</td><td>${escapeHTML(i.role||'Interview')}</td><td>${escapeHTML(i.date||'—')}</td><td>${escapeHTML(i.time||'—')}</td><td>${escapeHTML(i.mode||'—')}</td><td>${i.link?`<a href="${escapeHTML(i.link)}" target="_blank" rel="noopener">Open ↗</a>`:escapeHTML(i.venue||'—')}</td><td>${statusBadge(i.status||'Scheduled','active')}</td>${admin?`<td>${button('Edit','edit-interview:'+i.id,'secondary')}${button('Delete','delete-interview:'+i.id,'danger')}</td>`:''}</tr>`).join(''))}</section>`}
function renderOffers(){const admin=session.role==='admin';const rows=offers.filter(o=>admin||String(o.studentId)===String(session.student?.id));return `${pageHeading('Placement Offers',admin?'Record and manage offers made to students.':'Review your placement offers and package details.',admin?button('Record offer','add-offer','primary'):'')}<div class="tpo-stats">${tpoStat('Offer records',rows.length,'Visible offers','✉')}${tpoStat('Accepted',rows.filter(o=>o.status==='Accepted').length,'Accepted offers','✓')}${tpoStat('Average package',rows.length?'₹'+(rows.reduce((n,o)=>n+Number(o.package||0),0)/rows.length).toFixed(2)+' LPA':'—','Among visible offers','₹')}</div><section class="panel">${tpoTable(['Student','Company','Role','Package (LPA)','Offer date','Joining date','Status','Offer letter'],rows.map(o=>`<tr><td>${escapeHTML(studentName(o.studentId))}</td><td>${escapeHTML(companyName(o.companyId))}</td><td>${escapeHTML(o.role||'—')}</td><td>₹${escapeHTML(o.package||'—')}</td><td>${escapeHTML(o.date||'—')}</td><td>${escapeHTML(o.joining||'—')}</td><td>${statusBadge(o.status||'Offered','active')}</td><td>${o.letter?`<a href="${escapeHTML(o.letter)}" target="_blank" rel="noopener">View ↗</a>`:'—'} ${admin?button('Update','status-offer:'+o.id,'secondary'):''}</td></tr>`).join(''))}</section>`}
function renderTraining(){const admin=session.role==='admin';const rows=training.filter(t=>admin||!t.studentIds||t.studentIds.includes(String(session.student?.id)));return `${pageHeading('Placement Training',admin?'Plan employability training, aptitude practice, and mock interviews.':'View placement preparation activities and your progress.',admin?button('Add training','add-training','primary'):'')}<section class="panel">${tpoTable(['Training programme','Category','Trainer','Schedule','Mode','Target group','Status',...(admin?['Action']:[])],rows.map(t=>`<tr><td><b>${escapeHTML(t.title)}</b><small class="table-sub">${escapeHTML(t.description||'')}</small></td><td>${escapeHTML(t.category||'General')}</td><td>${escapeHTML(t.trainer||'—')}</td><td>${escapeHTML(t.date||'—')}</td><td>${escapeHTML(t.mode||'—')}</td><td>${escapeHTML(t.target||'All students')}</td><td>${statusBadge(t.status||'Scheduled','active')}</td>${admin?`<td>${button('Edit','edit-training:'+t.id,'secondary')}${button('Delete','delete-training:'+t.id,'danger')}</td>`:''}</tr>`).join(''))}</section>`}
function renderPlacementAnalytics(){if(session.role!=='admin')return `<section class="panel"><h2>Administrator access required</h2></section>`;const placed=new Set(offers.filter(o=>o.status!=='Declined').map(o=>String(o.studentId)));const total=students.length;const pct=total?Math.round(placed.size/total*100):0;const companiesCount={};offers.forEach(o=>companiesCount[companyName(o.companyId)]=(companiesCount[companyName(o.companyId)]||0)+1);return `${pageHeading('Placement Analytics','A high-level view of student placement outcomes.',button('Export placement report','export-placement-analytics','primary'))}<div class="tpo-stats">${tpoStat('Students',total,'Registered in institute')}${tpoStat('Students placed',placed.size,'Unique students')}${tpoStat('Placement rate',pct+'%','Offers recorded against student count')}${tpoStat('Average package',offers.length?'₹'+(offers.reduce((n,o)=>n+Number(o.package||0),0)/offers.length).toFixed(2)+' LPA':'—','Recorded offer package')}</div><div class="grid two-col"><section class="panel"><h3>Offers by Company</h3>${tpoTable(['Company','Offer records'],Object.entries(companiesCount).map(([n,c])=>`<tr><td>${escapeHTML(n)}</td><td>${c}</td></tr>`).join(''))}</section><section class="panel"><h3>Application Status</h3>${tpoTable(['Status','Count'],['Applied','Under Review','Shortlisted','Interview','Selected','Rejected'].map(st=>`<tr><td>${st}</td><td>${applications.filter(a=>a.status===st).length}</td></tr>`).join(''))}</section></div>`}
function addCompany(item){item=item||{};openModal(item.id?'Edit company':'Add recruiting company',formGrid([field('Company name','name',item.name||'','text','e.g. ABC Technologies',true),field('Industry','industry',item.industry||''),field('HR / Recruiter name','hr',item.hr||''),field('Email','email',item.email||'','email'),field('Phone','phone',item.phone||'','tel'),field('Website URL','website',item.website||'','url'),field('Status','status',item.status||'Active','text','',true,[{value:'Active',label:'Active'},{value:'Inactive',label:'Inactive'}])]),()=>{const name=formVal('name');if(!name){toast('Company name is required');return false}const data={id:item.id||uid(),name,industry:formVal('industry'),hr:formVal('hr'),email:formVal('email'),phone:formVal('phone'),website:formVal('website'),status:formVal('status')||'Active'};if(item.id)companies=companies.map(c=>c.id===item.id?data:c);else companies.push(data);saveAll();render();toast('Company saved');return true},'TPO · COMPANIES')}
function addJob(item){item=item||{};const opts=companies.map(c=>({value:c.id,label:c.name}));openModal(item.id?'Edit opportunity':'Post job / internship',formGrid([field('Job / internship title','title',item.title||'','text','Software Developer',true),field('Company','companyId',item.companyId||opts[0]?.value||'','text','Enter company ID',true,opts.length?opts:null),field('Type','type',item.type||'Full-time','text','',true,[{value:'Full-time',label:'Full-time'},{value:'Internship',label:'Internship'},{value:'Part-time',label:'Part-time'},{value:'Apprenticeship',label:'Apprenticeship'}]),field('Location','location',item.location||''),field('Package (LPA / stipend)','package',item.package||''),field('Eligibility','eligibility',item.eligibility||'e.g. MCA / B.Sc CS'),field('Application deadline','deadline',item.deadline||'','date'),field('Description','description',item.description||'','textarea'),field('Status','status',item.status||'Open','text','',true,[{value:'Open',label:'Open'},{value:'Closed',label:'Closed'}])]),()=>{const title=formVal('title');if(!title){toast('Job title is required');return false}const data={id:item.id||uid(),title,companyId:formVal('companyId'),type:formVal('type'),location:formVal('location'),package:formVal('package'),eligibility:formVal('eligibility'),deadline:formVal('deadline'),description:formVal('description'),status:formVal('status')||'Open',createdAt:today()};if(item.id)jobs=jobs.map(j=>j.id===item.id?data:j);else jobs.push(data);saveAll();render();toast('Opportunity saved');return true},'TPO · OPPORTUNITIES')}
function applyToJob(id){const job=jobs.find(j=>j.id===id);if(!job||job.status!=='Open'){toast('This opportunity is not open');return}const student=session.student;if(!student){toast('Sign in as a student to apply');return}if(applications.some(a=>a.jobId===id&&String(a.studentId)===String(student.id))){toast('You have already applied');return}openModal('Apply for '+job.title,formGrid([field('Resume URL (optional)','resume','','url','Paste a link to your resume'),field('Resume filename (optional)','resumeName','','text','e.g. Kamran_Resume.pdf'),field('Short cover note','note','','textarea','Why are you interested?')]),()=>{applications.push({id:uid(),jobId:id,studentId:student.id,resume:formVal('resume'),resumeName:formVal('resumeName'),note:formVal('note'),appliedOn:today(),status:'Applied'});saveAll();render();toast('Application submitted');return true},'STUDENT CAREERS')}
