function render(){const meta=pageMeta[currentPage]||pageMeta.dashboard;$('#topTitle').textContent=meta[0];$('#topSubtitle').textContent=meta[1];$('#navStudentCount').textContent=students.length;$('#footerOrg').textContent=settings?.org||'KK EduTech Solutions';$('#userName').textContent=session?.role==='admin'?'Administrator':(session?.role==='staff'?session?.staff?.name:(session?.student?.name||'Student'));$('#userRoleLabel').textContent=session?.role==='admin'?'Institute Admin':(session?.role==='staff'?'Staff Portal':'Student Portal');$('#userAvatar').textContent=session?.role==='admin'?'KK':initials(session?.role==='staff'?session?.staff?.name:session?.student?.name);$$('#mainNav .nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===currentPage));$$('.admin-only').forEach(el=>el.classList.toggle('hidden',session?.role!=='admin'));try{const pageRenderer=({'tpo-dashboard':renderTpoDashboard,companies:renderCompanies,jobs:renderJobs,applications:renderApplications,interviews:renderInterviews,offers:renderOffers,training:renderTraining,'placement-analytics':renderPlacementAnalytics,profile:renderProfilePage,dashboard:renderDashboard,students:renderStudentsPage,attendance:renderAttendancePage,results:renderResultsPage,library:renderLibraryPage,fees:renderFeesPage,timetable:renderTimetablePage,notices:renderNoticesPage,staff:renderStaffPage,'staff-attendance':renderStaffAttendancePage,reports:renderReportsPage,settings:renderSettingsPage}[currentPage]||renderDashboard);const html=pageRenderer();$('#pageContent').innerHTML=(typeof html==='string'&&html.trim())?html:`<section class="panel"><h2>Page is empty</h2><p>This section did not return any content. Try another menu item.</p></section>`;document.body.classList.toggle('dark-mode',!!settings?.dark);$('#appShell').classList.remove('sidebar-open');}catch(error){console.error('KK Institute Suite render error:',error);$('#pageContent').innerHTML=`<section class="panel render-error"><div style="font-size:32px;margin-bottom:12px">⚠️</div><h2>We couldn't load this page</h2><p>The page encountered an error while rendering. Your saved student and attendance data have not been deleted.</p><details><summary>Technical details</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${escapeHTML(error?.stack||error?.message||String(error))}</pre></details><button class="btn btn-primary" data-action="retry-render">Try again</button><button class="btn btn-ghost" data-page="dashboard">Back to dashboard</button></section>`;$('#appShell').classList.remove('sidebar-open');}}
function go(page){if(!pageMeta[page])return;if(session?.role!=='admin'&&['students','attendance','staff','staff-attendance','reports','settings','companies','tpo-dashboard','placement-analytics'].includes(page)&&!(session?.role==='staff'&&page==='staff-attendance')){toast('This section is available to administrators.');return}currentPage=page;render();$('#pageContent').focus({preventScroll:true});}

function renderProfilePage(){
 const admin=session?.role==='admin',isStaff=session?.role==='staff';
 const p=admin?(settings.adminProfile||{name:'Administrator',email:'admin@kkedutech.example',phone:'',designation:'Institute Administrator'}):(isStaff?session?.staff:session?.student)||{};
 const title=admin?'Administrator Profile':(isStaff?'Staff Profile':'My Student Profile');
 const rows=admin?[
 ['Full name',p.name||'Administrator'],['Role / Designation',p.designation||'Institute Administrator'],
 ['Email address',p.email||'Not provided'],['Phone number',p.phone||'Not provided'],
 ['Organization',settings.org||'KK EduTech Solutions'],['Access level','Administrator']
 ]:isStaff?[
 ['Full name',p.name],['Staff ID',p.staffId],['Department',p.department],['Designation',p.designation],['Email address',p.email],['Phone number',p.phone],['Access level','Staff / Faculty']
 ]:[
 ['Full name',p.name],['Student ID / Roll number',p.id],['Class / Programme',p.studentClass],
 ['Email address',p.email],['Phone number',p.phone],['Date of birth',fmtDate(p.dob)],['Gender',p.gender],['Parent / guardian',p.guardian],['Address',p.address],['Admission date',fmtDate(p.admissionDate)],
 ['Account status','Active']
 ];
 const photo=p.photo||'';
 const profileAvatar=photo?`<img src="${escapeHTML(photo)}" alt="Profile photo" class="profile-photo-large">`:`<span class="profile-initials">${escapeHTML(initials(p.name|| (admin?'Administrator':'Student')))}</span>`;
 const editBtn=admin?button('Edit profile','edit-admin-profile','primary'):'';
 return `${pageHeading(title,admin?'Manage administrator contact details and account identity.':'View your registered personal and academic details.',editBtn+button('Print profile','print-profile'))}
 <section class="panel profile-hero"><div class="profile-hero-avatar">${profileAvatar}</div><div class="profile-hero-info"><p class="eyebrow">${admin?'ADMINISTRATOR ACCOUNT':(isStaff?'STAFF ACCOUNT':'STUDENT ACCOUNT')}</p><h2>${escapeHTML(p.name|| (admin?'Administrator':'Student'))}</h2><p>${escapeHTML(p.designation||p.studentClass|| (admin?'Institute Admin':'Student'))} · ${escapeHTML(p.id||'KK Institute Suite')}</p><span class="status status-active">● Active account</span></div></section>
 <section class="panel"><div class="panel-heading"><div><h3>Complete Profile Information</h3><p>${admin?'Administrator details':'Information registered by your institute'}</p></div></div><div class="table-wrap"><table class="profile-table"><thead><tr><th>Information field</th><th>Details</th></tr></thead><tbody>${rows.map(([k,v])=>`<tr><th scope="row">${escapeHTML(k)}</th><td>${escapeHTML(v||'Not provided')}</td></tr>`).join('')}</tbody></table></div>${admin?'<p class="muted profile-note">Administrator profile details are stored locally in this browser in this demo.</p>':'<p class="muted profile-note">For corrections to your student ID, class, email, phone, or admission details, contact the institute administrator.</p>'}</section>
 ${admin?`<section class="panel"><div class="panel-heading"><div><h3>Account & Workspace</h3><p>Administrator access summary</p></div></div><div class="profile-facts"><div><span>Role</span><b>Administrator</b></div><div><span>Registered students</span><b>${students.length}</b></div><div><span>Workspace</span><b>${escapeHTML(settings.title||'KK Institute Suite')}</b></div></div></section>`:''}`;
}


function renderStaffDashboard(){
 const t=session.staff, sid=t.staffId, rows=Object.entries(staffAttendance).filter(([d,m])=>m&&m[sid]).sort(([a],[b])=>b.localeCompare(a));
 const counts={Present:0,Absent:0,Late:0};rows.forEach(([d,m])=>{if(counts[m[sid]]!==undefined)counts[m[sid]]++});
 return `<section class="greeting-row"><div><p class="eyebrow" style="color:#8be0bb">STAFF WORKSPACE</p><h1>Welcome back, ${escapeHTML(t.name)} ✨</h1><p>Your staff profile, attendance and institute updates in one place.</p></div><div class="date-chip"><small>STAFF ID · ${escapeHTML(t.staffId)}</small><b>${escapeHTML(t.department||'Faculty & Staff')}</b></div></section>
 <div class="stats-grid">${summaryCard('Present days',counts.Present,'✓','green','Attendance history')}${summaryCard('Absent days',counts.Absent,'!','red','Attendance history')}${summaryCard('Late days',counts.Late,'◷','amber','Attendance history')}${summaryCard('Total marked',rows.length,'▥','blue','Recorded entries')}</div>
 <div class="grid dashboard-grid"><section class="panel"><div class="panel-heading"><div><h3>Recent attendance</h3><p>Latest attendance entries</p></div><button class="panel-link" data-page="staff-attendance">View all →</button></div>${tpoTable(['Date','Status'],rows.slice(0,7).map(([d,m])=>`<tr><td>${fmtDate(d)}</td><td>${statusBadge(m[sid],m[sid].toLowerCase())}</td></tr>`).join(''))}</section><section class="panel"><h3>My staff profile</h3><div class="report-summary-grid"><div class="report-mini"><span>Designation</span><b style="font-size:13px">${escapeHTML(t.designation||'Staff')}</b></div><div class="report-mini"><span>Department</span><b style="font-size:13px">${escapeHTML(t.department||'—')}</b></div><div class="report-mini"><span>Email</span><b style="font-size:11px;word-break:break-word">${escapeHTML(t.email||'Not added')}</b></div></div><button class="btn btn-ghost btn-small" data-page="profile">View profile →</button></section></div>`;
}
function renderDashboard(){if(session.role==='staff')return renderStaffDashboard();const admin=session.role==='admin',s=session.student;const stats=attendanceStats(monthRecords());const todayRecords=allAttendanceRecords().filter(r=>r.date===today());const todayStat=attendanceStats(todayRecords);const myAtt=s?studentAttendance(s.id,monthNow()):null;const activeStudents=students.length;const low=students.filter(st=>{const x=studentAttendance(st.id,monthNow());return x.rate!==null&&x.rate<Number(settings.threshold||75)}).length;
let greeting=admin?'Welcome back, Administrator':`Welcome back, ${escapeHTML(s.name)}`;let mainStats=admin?[summaryCard('Total students',activeStudents,'♙','blue','Across all registered classes'),summaryCard('Present today',todayStat.p,'✓','green','Saved attendance entries'),summaryCard('Needs attention',low,'!','red',`Below ${settings.threshold}% attendance`),summaryCard('Monthly attendance',stats.rate+'%','▥','amber',monthName(monthNow())),summaryCard('Total staff',staff.length,'♧','blue','Registered faculty & staff'),summaryCard('Staff present today',Object.values(staffAttendance[today()]||{}).filter(v=>v==='Present').length,'✓','green','Saved staff attendance')].join(''):[summaryCard('My attendance',myAtt?.rate===null||myAtt?.rate===undefined?'N/A':myAtt.rate+'%','✓','green',monthName(monthNow())),summaryCard('Published results',results.filter(r=>String(r.studentId)===String(s.id)&&r.status==='Published').length,'▤','blue','Available to view'),summaryCard('Library resources',library.filter(r=>!r.className||r.className===s.studentClass).length,'▣','amber','Available to your class'),summaryCard('Notices',notices.length,'◉','green','Institute announcements')].join('');
const daily=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const key=d.toISOString().slice(0,10);const stat=attendanceStats(allAttendanceRecords().filter(r=>r.date===key));return {key,label:d.toLocaleDateString('en-IN',{weekday:'short'}),...stat}});const max=Math.max(1,...daily.map(d=>d.p+d.a+d.l));const chart=`<div class="mini-bars">${daily.map(d=>`<div class="bar-group"><div class="bar-pair"><div class="bar present" style="height:${d.p/max*100}%" title="Present ${d.p}"></div><div class="bar absent" style="height:${d.a/max*100}%" title="Absent ${d.a}"></div><div class="bar late" style="height:${d.l/max*100}%" title="Late ${d.l}"></div></div><span class="bar-label">${d.label}</span></div>`).join('')}</div><div class="legend"><span><i style="background:#0c9b66"></i>Present</span><span><i style="background:#e05252"></i>Absent</span><span><i style="background:#e7a923"></i>Late</span></div>`;
const recent=students.slice(-5).reverse();const recentTable=recent.length?`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>Attendance</th><th>Status</th></tr></thead><tbody>${recent.map(st=>{const a=studentAttendance(st.id,monthNow());return `<tr><td>${initialsCell(st)}</td><td>${escapeHTML(st.studentClass||'—')}</td><td>${a.rate===null?'N/A':a.rate+'%'}</td><td>${a.rate===null?statusBadge('Not marked'):a.rate<settings.threshold?statusBadge('Low','low'):statusBadge('On track','active')}</td></tr>`}).join('')}</tbody></table></div>`:emptyState('♙','No students yet','Register your first student to begin.',admin?button('+ Add student','add-student','primary'):'' );
const studentPanel=admin?`<section class="table-panel"><div class="panel-heading"><div><h3>Recently registered students</h3><p>Latest student directory activity</p></div><button class="panel-link" data-page="students">View directory →</button></div>${recentTable}</section>`:`<section class="panel"><div class="panel-heading"><div><h3>My academic snapshot</h3><p>Your current profile information</p></div></div><div class="report-summary-grid"><div class="report-mini"><span>Student ID</span><b style="font-size:14px">${escapeHTML(s.id)}</b></div><div class="report-mini"><span>Class</span><b style="font-size:14px">${escapeHTML(s.studentClass||'—')}</b></div><div class="report-mini"><span>Email</span><b style="font-size:12px;word-break:break-word">${escapeHTML(s.email||'Not added')}</b></div></div><button class="btn btn-ghost btn-small" data-page="results">View exam results →</button></section>`;
return `${`<section class="greeting-row"><div><p class="eyebrow" style="color:#8be0bb">${admin?'INSTITUTE OVERVIEW':'STUDENT WORKSPACE'}</p><h1>${greeting} ✨</h1><p>${admin?'Your campus operations, academics, and student services in one place.':'Here is your academic activity and the resources available to you.'}</p></div><div class="date-chip"><small>TODAY · ACADEMIC YEAR ${escapeHTML(settings.year)}</small><b>${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}</b></div></section>`}<section class="grid stats-grid">${mainStats}</section><section class="grid dashboard-grid"><div><section class="panel"><div class="panel-heading"><div><h3>${admin?'Weekly attendance activity':'Institute attendance activity'}</h3><p>Saved attendance over the last seven days</p></div><span class="status status-neutral">7 days</span></div>${chart}</section>${studentPanel}</div><div><section class="panel"><div class="panel-heading"><div><h3>Quick actions</h3><p>Common tasks for your workspace</p></div></div><div class="quick-actions">${(admin?[['♙','Add student','Register a new student','add-student'],['✓','Take attendance','Mark a class register','attendance'],['▤','Add result','Record exam marks','add-result'],['▣','Add resource','Publish library material','add-resource'],['＄','Record payment','Update fee status','add-fee'],['◉','Post notice','Share an announcement','add-notice']]:[['▤','My results','Review published results','results'],['▣','Open library','Browse learning resources','library'],['▦','Timetable','View weekly schedule','timetable'],['◉','Notice board','Read announcements','notices']]).map(([ico,title,desc,act])=>`<button class="quick-action" data-action="${act}"><span class="qa-icon">${ico}</span><span><b>${title}</b><small>${desc}</small></span></button>`).join('')}</div></section><section class="panel"><div class="panel-heading"><div><h3>Latest notices</h3><p>Important institute updates</p></div><button class="panel-link" data-page="notices">View all</button></div>${notices.slice(0,3).map(n=>`<div class="notice-item"><span class="notice-bullet">◉</span><div><h3>${escapeHTML(n.title)}</h3><p>${escapeHTML(n.body)}</p><small>${fmtDate(n.date||today())}</small></div></div>`).join('')||emptyState('◉','No notices posted','Announcements will appear here.')}</section></div></section>`}
function renderStudentsPage(){const q=($('#studentSearch')?.value||'').toLowerCase();const cls=$('#studentClassFilter')?.value||'';const filtered=students.filter(s=>(!q||`${s.name} ${s.id} ${s.studentClass} ${s.email}`.toLowerCase().includes(q))&&(!cls||s.studentClass===cls));return `${pageHeading('Student Directory','Maintain student profiles, enrolment details, and academic status.',button('+ Add student','add-student','primary')+button('Import CSV','import-students')+button('Export CSV','export-students'))}<section class="panel"><div class="toolbar"><input id="studentSearch" placeholder="Search name, student ID, email..." value="${escapeHTML(q)}"><select id="studentClassFilter"><option value="">All classes</option>${[...new Set(students.map(s=>s.studentClass).filter(Boolean))].sort().map(c=>`<option ${c===cls?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select><span class="status status-neutral">${filtered.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Student ID</th><th>Class</th><th>Monthly attendance</th><th>Account</th><th>Actions</th></tr></thead><tbody>${filtered.map(s=>{const a=studentAttendance(s.id,monthNow());return `<tr><td>${initialsCell(s)}</td><td>${escapeHTML(s.id)}</td><td>${escapeHTML(s.studentClass)}</td><td>${a.rate===null?'N/A':a.rate+'%'} ${a.rate!==null&&a.rate<settings.threshold?statusBadge('Low','low'):''}</td><td>${statusBadge('Active','active')}</td><td><div class="row-actions">${button('Edit','edit-student:'+s.id)} ${button('Delete','delete-student:'+s.id,'danger')}</div></td></tr>`}).join('')}</tbody></table></div>${!filtered.length?emptyState('♙','No matching students','Add a student or adjust your search.',button('+ Add student','add-student','primary')):''}</section>`}
function renderAttendancePage(){const cls=$('#attClass')?.value||'';const date=$('#attDate')?.value||today();const rec=attendance[`${date}__${cls}`]||{};const rows=students.filter(s=>!cls||s.studentClass===cls);return `${pageHeading('Attendance Management','Record daily attendance and monitor class participation.',button('Export attendance','export-attendance'))}<section class="panel"><div class="attendance-toolbar"><div class="field"><label>Attendance date</label><input id="attDate" type="date" value="${date}"></div><div class="field"><label>Class</label><select id="attClass"><option value="">All classes</option>${[...new Set(students.map(s=>s.studentClass).filter(Boolean))].map(c=>`<option ${c===cls?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select></div><div>${button('Mark all present','mark-all','secondary',false)}</div></div><div class="attendance-scroll"><div class="attendance-row head"><span>Student</span><span>Present</span><span>Absent</span><span>Late</span><span>Status</span></div>${rows.map(s=>{const status=rec.students?.[s.id]||'';return `<div class="attendance-row"><span class="attendance-name"><b>${escapeHTML(s.name)}</b><small>${escapeHTML(s.id)} · ${escapeHTML(s.studentClass)}</small></span>${['Present','Absent','Late'].map(v=>`<span><input type="radio" name="att-${escapeHTML(s.id)}" value="${v}" ${status===v?'checked':''} aria-label="${v} for ${escapeHTML(s.name)}"></span>`).join('')}<span>${status?statusBadge(status,status.toLowerCase()):statusBadge('Unmarked')}</span></div>`}).join('')||emptyState('✓','No students found','Register students before marking attendance.')}</div><div class="toolbar" style="margin-top:17px"><button class="btn btn-primary" data-action="save-attendance">Save attendance</button><button class="btn btn-ghost" data-action="clear-attendance">Clear marks</button><span class="muted">Only saved records count in reports.</span></div></section><section class="panel"><div class="panel-heading"><div><h3>Recent attendance records</h3><p>Most recent saved class sessions</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Class</th><th>Present</th><th>Absent</th><th>Late</th><th>Actions</th></tr></thead><tbody>${allAttendanceRecords().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12).map(r=>{const st=attendanceStats([r]);return `<tr><td>${fmtDate(r.date)}</td><td>${escapeHTML(r.className)}</td><td>${st.p}</td><td>${st.a}</td><td>${st.l}</td><td>${button('Load','load-attendance:'+r.date+':'+encodeURIComponent(r.className))}</td></tr>`}).join('')}</tbody></table></div></section>`}
function renderResultsPage(){const own=session.role==='student';const list=results.filter(r=>(!own||String(r.studentId)===String(session.student.id))&&(!own||r.status==='Published'));return `${pageHeading(own?'My Exam Results':'Exams & Results',own?'Review your published assessment results and academic progress.':'Create exam records, enter marks, and publish results for student access.',own?'':button('+ Add result','add-result','primary')+button('Export results','export-results'))}<section class="panel"><div class="toolbar"><input id="resultSearch" placeholder="Search student, exam, subject..." ><select id="resultStatus"><option value="">All statuses</option><option>Published</option><option>Draft</option></select></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Exam / Semester</th><th>Subject</th><th>Marks</th><th>Grade</th><th>Status</th>${own?'':'<th>Actions</th>'}</tr></thead><tbody>${list.map(r=>`<tr><td>${escapeHTML(studentName(r.studentId))}<small style="display:block;color:#8a97a7;margin-top:4px">${escapeHTML(r.studentId)}</small></td><td>${escapeHTML(r.exam||'—')}</td><td>${escapeHTML(r.subject||'—')}</td><td>${escapeHTML(r.marks)}/${escapeHTML(r.maxMarks||100)} <small>(${Math.round(Number(r.marks)/(Number(r.maxMarks)||100)*100)}%)</small></td><td><b>${escapeHTML(r.grade||gradeFor(r.marks,r.maxMarks))}</b></td><td>${statusBadge(r.status||'Draft',(r.status||'Draft').toLowerCase())}</td>${own?'':`<td>${button(r.status==='Published'?'Unpublish':'Publish','toggle-result:'+r.id)} ${button('Delete','delete-result:'+r.id,'danger')}</td>`}</tr>`).join('')}</tbody></table></div>${!list.length?emptyState('▤',own?'No published results yet':'No exam records yet',own?'Your published results will appear here.':'Add exam results and publish them for student access.',own?'':button('+ Add result','add-result','primary')):''}</section>`}
function gradeFor(m,max=100){const p=Number(m)/(Number(max)||100)*100;return p>=90?'O':p>=80?'A+':p>=70?'A':p>=60?'B+':p>=50?'B':p>=40?'C':'RA'}
function renderLibraryPage(){const own=session.role==='student';const list=library.filter(r=>!own||!r.className||r.className===session.student.studentClass);return `${pageHeading('Digital Library',own?'Study notes, question papers, and resources for your class.':'Organize learning resources and publish material for student access.',own?'':button('+ Add resource','add-resource','primary')+button('Export list','export-library'))}<div class="toolbar"><input id="librarySearch" placeholder="Search title, subject, type..."><select id="libraryType"><option value="">All resource types</option>${['Notes','Book','Question Paper','Video','Link','Assignment','Other'].map(t=>`<option>${t}</option>`).join('')}</select><select id="libraryClass"><option value="">All classes</option>${[...new Set(students.map(s=>s.studentClass).filter(Boolean))].map(c=>`<option>${escapeHTML(c)}</option>`).join('')}</select></div><section class="library-grid">${list.map(r=>`<article class="resource-card"><span class="resource-icon">${({Notes:'▤',Book:'▣','Question Paper':'✎',Video:'▷',Link:'↗',Assignment:'✓'}[r.type]||'▧')}</span><h3>${escapeHTML(r.title)}</h3><p>${escapeHTML(r.description||'Learning resource published by the institute.')}</p><div class="resource-meta"><span>${escapeHTML(r.type||'Resource')} · ${escapeHTML(r.className||'All classes')}</span><span>${r.url?`<a href="${escapeHTML(r.url)}" target="_blank" rel="noopener">Open ↗</a>`:''} ${own?'':button('Delete','delete-resource:'+r.id,'danger')}</span></div></article>`).join('')}</section>${!list.length?`<section class="panel">${emptyState('▣','Library is ready for resources','Add notes, books, question papers, videos, or reference links.',own?'':button('+ Add resource','add-resource','primary'))}</section>`:''}`}
function renderFeesPage(){const own=session.role==='student';const q=$('#feeSearch')?.value?.toLowerCase()||'';const list=fees.filter(f=>(!own||String(f.studentId)===String(session.student.id))&&(!q||`${studentName(f.studentId)} ${f.studentId} ${f.term}`.toLowerCase().includes(q)));const total=list.reduce((s,f)=>s+Number(f.amount||0),0),paid=list.filter(f=>f.status==='Paid').reduce((s,f)=>s+Number(f.amount||0),0);return `${pageHeading(own?'My Fees & Payments':'Fees & Payments',own?'Review your fee entries and payment status.':'Track fee schedules, collections, and outstanding balances.',own?'':button('+ Record payment','add-fee','primary')+button('Export CSV','export-fees'))}<section class="grid stats-grid">${summaryCard('Total fee entries',fees.length,'＄','blue','All recorded entries')}${summaryCard('Recorded amount','₹'+total.toLocaleString('en-IN'),'▤','green','All fee records')}${summaryCard('Paid amount','₹'+paid.toLocaleString('en-IN'),'✓','green','Marked as paid')}${summaryCard('Outstanding','₹'+(total-paid).toLocaleString('en-IN'),'!','amber','Not marked paid')}</section><section class="panel"><div class="toolbar"><input id="feeSearch" placeholder="Search student or fee term..." value="${escapeHTML(q)}"></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Fee term</th><th>Amount</th><th>Due date</th><th>Status</th><th>Actions</th></tr></thead><tbody>${list.map(f=>`<tr><td>${escapeHTML(studentName(f.studentId))} <small style="display:block;color:#8a97a7;margin-top:3px">${escapeHTML(f.studentId)}</small></td><td>${escapeHTML(f.term)}</td><td>₹${Number(f.amount).toLocaleString('en-IN')}</td><td>${fmtDate(f.dueDate)}</td><td>${statusBadge(f.status,f.status==='Paid'?'paid':f.status==='Overdue'?'overdue':'pending')}</td><td>${button(f.status==='Paid'?'Mark due':'Mark paid','toggle-fee:'+f.id)} ${button('Delete','delete-fee:'+f.id,'danger')}</td></tr>`).join('')}</tbody></table></div>${!list.length?emptyState('＄','No fee records','Record a fee or payment to begin.',button('+ Record payment','add-fee','primary')):''}</section>`}
function renderTimetablePage(){const own=session.role==='student';const cls=own?session.student.studentClass:($('#ttClass')?.value||'');const list=timetable.filter(t=>!cls||t.className===cls);const days=['Monday','Tuesday','Wednesday','Thursday','Friday'];return `${pageHeading('Academic Timetable','Weekly class schedule, faculty allocation, and classroom planning.',own?'':button('+ Add class session','add-timetable','primary'))}${own?'':`<div class="toolbar"><select id="ttClass"><option value="">All classes</option>${[...new Set(students.map(s=>s.studentClass).filter(Boolean))].map(c=>`<option ${c===cls?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select></div>`}<section class="panel"><div class="week-grid">${days.map(day=>`<div class="week-day"><h3>${day}</h3>${list.filter(t=>t.day===day).sort((a,b)=>(a.start||'').localeCompare(b.start||'')).map(t=>`<div class="class-slot"><b>${escapeHTML(t.subject)}</b><small>${escapeHTML(t.start||'—')} – ${escapeHTML(t.end||'—')}</small><small>${escapeHTML(t.className)} · ${escapeHTML(t.faculty||'Faculty TBA')}</small>${own?'':button('Delete','delete-timetable:'+t.id,'danger')}</div>`).join('')||'<div style="padding:12px;font-size:10px;color:#9aa6b5">No sessions</div>'}</div>`).join('')}</div></section>${!list.length?`<section class="panel">${emptyState('▦','No timetable sessions','Add class sessions to build the weekly timetable.',own?'':button('+ Add class session','add-timetable','primary'))}</section>`:''}`}
function renderNoticesPage(){const own=session.role==='student';return `${pageHeading('Notice Board','Official announcements, deadlines, events, and campus updates.',own?'':button('+ Post notice','add-notice','primary'))}<section class="panel">${[...notices].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(n=>`<article class="notice-item"><span class="notice-bullet">◉</span><div style="flex:1"><h3>${escapeHTML(n.title)}</h3><p>${escapeHTML(n.body)}</p><small>${fmtDate(n.date||today())} · ${escapeHTML(n.audience||'Everyone')}</small></div>${own?'':button('Delete','delete-notice:'+n.id,'danger')}</article>`).join('')||emptyState('◉','No announcements yet','Important notices published by the institute will appear here.',own?'':button('+ Post notice','add-notice','primary'))}</section>`}

function renderStaffAttendancePage(){
 const admin=session.role==='admin';
 if(!admin){
   const sid=session.staff.staffId, records=Object.entries(staffAttendance).filter(([d,marks])=>marks&&marks[sid]).sort(([a],[b])=>b.localeCompare(a));
   const present=records.filter(([d,m])=>m[sid]==='Present').length, absent=records.filter(([d,m])=>m[sid]==='Absent').length, late=records.filter(([d,m])=>m[sid]==='Late').length;
   return `${pageHeading('My Attendance','Your personal staff attendance record and monthly history.')}
   <div class="stats-grid">${summaryCard('Present',present,'✓','green','Recorded days')}${summaryCard('Absent',absent,'!','red','Recorded days')}${summaryCard('Late',late,'◷','amber','Recorded days')}${summaryCard('Total marked',records.length,'▥','blue','Attendance entries')}</div>
   <section class="panel"><div class="panel-heading"><div><h3>My attendance history</h3><p>Attendance recorded by the institute administrator.</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Status</th></tr></thead><tbody>${records.map(([d,m])=>`<tr><td>${fmtDate(d)}</td><td>${statusBadge(m[sid],m[sid].toLowerCase())}</td></tr>`).join('')}</tbody></table></div>${!records.length?emptyState('◷','No attendance records yet','Your attendance will appear here after it is marked by the administrator.'):''}</section>`;
 }
 const date=$('#staffAttDate')?.value||today(),marks=staffAttendance[date]||{};
 return `${pageHeading('Staff Attendance','Mark and review attendance for all faculty and staff members.',button('Export staff attendance','export-staff-attendance'))}
 <section class="panel"><div class="attendance-toolbar"><div class="field"><label>Attendance date</label><input id="staffAttDate" type="date" max="${today()}" value="${date}"></div><div class="field"><label>Staff members</label><input value="${staff.length} registered staff" disabled></div><div>${button('Mark all present','staff-mark-all','secondary',false)}</div></div>
 <div class="attendance-scroll"><div class="attendance-row head"><span>Staff member</span><span>Present</span><span>Absent</span><span>Late</span><span>Status</span></div>
 ${staff.map(t=>{const v=marks[t.staffId]||'';return `<div class="attendance-row"><span class="attendance-name"><b>${escapeHTML(t.name)}</b><small>${escapeHTML(t.staffId)} · ${escapeHTML(t.department||'')}</small></span>${['Present','Absent','Late'].map(x=>`<span><input type="radio" name="staff-att-${escapeHTML(t.staffId)}" value="${x}" ${v===x?'checked':''} aria-label="${x} for ${escapeHTML(t.name)}"></span>`).join('')}<span>${v?statusBadge(v,v.toLowerCase()):statusBadge('Unmarked')}</span></div>`}).join('')||emptyState('♧','No staff records','Add faculty and staff members first.',button('Add staff member','add-staff','primary'))}
 </div><div class="toolbar" style="margin-top:17px"><button class="btn btn-primary" data-action="save-staff-attendance">Save staff attendance</button><span class="muted">Only administrators can mark or edit staff attendance.</span></div></section>
 <section class="panel"><div class="panel-heading"><div><h3>Recent staff attendance</h3><p>Daily attendance summary</p></div></div>${tpoTable(['Date','Present','Absent','Late','Marked'],Object.entries(staffAttendance).sort(([a],[b])=>b.localeCompare(a)).slice(0,12).map(([d,m])=>{const vals=Object.values(m||{});return `<tr><td>${fmtDate(d)}</td><td>${vals.filter(x=>x==='Present').length}</td><td>${vals.filter(x=>x==='Absent').length}</td><td>${vals.filter(x=>x==='Late').length}</td><td>${vals.length}/${staff.length}</td></tr>`}).join(''))}</section>`;
}
function renderStaffPage(){return `${pageHeading('Faculty & Staff','Maintain faculty, department, and administrative contact records.',button('+ Add staff member','add-staff','primary')+button('Export CSV','export-staff'))}<section class="panel"><div class="toolbar"><input id="staffSearch" placeholder="Search name, department, designation..."></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Staff ID</th><th>Department</th><th>Designation</th><th>Email</th><th>Actions</th></tr></thead><tbody>${staff.map(s=>`<tr><td>${initialsCell(s)}</td><td>${escapeHTML(s.staffId||'—')}</td><td>${escapeHTML(s.department||'—')}</td><td>${escapeHTML(s.designation||'—')}</td><td>${escapeHTML(s.email||'—')}</td><td>${button('Edit','edit-staff:'+s.id)} ${button('Delete','delete-staff:'+s.id,'danger')}</td></tr>`).join('')}</tbody></table></div>${!staff.length?emptyState('♧','No staff records','Add faculty and administrative staff details.',button('+ Add staff member','add-staff','primary')):''}</section>`}
function renderReportsPage(){const m=$('#reportMonth')?.value||monthNow();const cls=$('#reportClass')?.value||'';const records=monthRecords(m,cls);const st=attendanceStats(records);const low=students.map(s=>({s,a:studentAttendance(s.id,m)})).filter(x=>x.a.rate!==null&&x.a.rate<settings.threshold);return `${pageHeading('Reports & Analytics','Review institute-wide attendance and export operational data.',button('Export monthly report','export-month-report','primary')+button('Backup all data','backup-data'))}<section class="toolbar"><div class="field"><label>Report month</label><input type="month" id="reportMonth" value="${m}"></div><div class="field"><label>Class filter</label><select id="reportClass"><option value="">All classes</option>${[...new Set(students.map(s=>s.studentClass).filter(Boolean))].map(c=>`<option ${c===cls?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select></div></section><section class="grid stats-grid">${summaryCard('Students',students.length,'♙','blue','Registered students')}${summaryCard('Present',st.p,'✓','green','Monthly saved marks')}${summaryCard('Absent',st.a,'×','red','Monthly saved marks')}${summaryCard('Attendance rate',st.rate+'%','▥','amber',monthName(m))}</section><section class="panel"><div class="panel-heading"><div><h3>Attendance by date</h3><p>Daily counts from saved attendance sessions</p></div></div>${renderMonthChart(records)}</section><section class="panel"><div class="panel-heading"><div><h3>Students below attendance threshold</h3><p>Configured threshold: ${settings.threshold}%</p></div><span class="status status-low">${low.length} flagged</span></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>Present</th><th>Absent</th><th>Late</th><th>Rate</th></tr></thead><tbody>${low.map(({s,a})=>`<tr><td>${initialsCell(s)}</td><td>${escapeHTML(s.studentClass)}</td><td>${a.Present}</td><td>${a.Absent}</td><td>${a.Late}</td><td>${statusBadge(a.rate+'%','low')}</td></tr>`).join('')}</tbody></table></div>${!low.length?'<p class="muted">No students are below the threshold for this month.</p>':''}</section>`}
function renderMonthChart(records){const by={};records.forEach(r=>{const st=attendanceStats([r]);by[r.date]=(by[r.date]||{p:0,a:0,l:0});by[r.date].p+=st.p;by[r.date].a+=st.a;by[r.date].l+=st.l});const arr=Object.entries(by).sort(([a],[b])=>a.localeCompare(b));const max=Math.max(1,...arr.map(([k,v])=>v.p+v.a+v.l));return arr.length?`<div class="mini-bars">${arr.map(([d,v])=>`<div class="bar-group"><div class="bar-pair"><div class="bar present" style="height:${v.p/max*100}%" title="Present ${v.p}"></div><div class="bar absent" style="height:${v.a/max*100}%" title="Absent ${v.a}"></div><div class="bar late" style="height:${v.l/max*100}%" title="Late ${v.l}"></div></div><span class="bar-label">${d.slice(8)}</span></div>`).join('')}</div><div class="legend"><span><i style="background:#0c9b66"></i>Present</span><span><i style="background:#e05252"></i>Absent</span><span><i style="background:#e7a923"></i>Late</span></div>`:emptyState('▥','No attendance data','Saved attendance will appear in this chart.')}
function renderSettingsPage(){return `${pageHeading('Institute Settings','Customize organization identity, academic year, and attendance policy.',button('Save settings','save-settings','primary'))}<div class="settings-grid"><section class="settings-section"><h3>Organization profile</h3><p>Branding details used across the workspace.</p>${field('Organization name','org',settings.org)}${field('Application title','title',settings.title)}${field('Academic year','year',settings.year)}${field('Low attendance threshold (%)','threshold',settings.threshold,'number','75',true)}</section><section class="settings-section"><h3>Appearance & workspace</h3><p>Choose your preferred workspace display.</p><label style="display:flex;gap:9px;align-items:center;margin:17px 0"><input id="darkModeSetting" type="checkbox" ${settings.dark?'checked':''} style="width:auto"> Enable dark mode</label><p class="form-note">Sidebar navigation is scrollable. On mobile, use the menu button to open it.</p><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><h3>Data management</h3><p>Download a backup before making major changes.</p><div class="toolbar">${button('Download backup','backup-data','primary')}<label class="btn btn-ghost btn-small" for="restoreFile">Restore backup<input id="restoreFile" type="file" accept="application/json" hidden></label></div><p class="form-note">Restoring replaces this browser's current application data. Back up first.</p></section></div><section class="panel" style="margin-top:17px"><h3 style="font:800 13px Manrope">Data storage notice</h3><p class="muted" style="font-size:11px;line-height:1.7">This build stores records in this browser using LocalStorage and preserves the legacy student and attendance keys. It is suitable for a local prototype. Do not use demo login or browser-only storage for sensitive real student data or multi-computer production use.</p></section>`}
function renderSimpleTable(title,desc,headers,rows){return `${pageHeading(title,desc)}<section class="panel"><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div></section>`}
function downloadText(filename,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvEscape(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}function downloadCSV(name,rows){downloadText(name,'\uFEFF'+rows.map(r=>r.map(csvEscape).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function backupData(){const data={version:2,exportedAt:new Date().toISOString(),stores:{}};Object.values(STORE).forEach(k=>data.stores[k]=read(k,k===STORE.students?[]:{}));downloadText('KK-Institute-Backup-'+today()+'.json',JSON.stringify(data,null,2),'application/json');toast('Backup downloaded')}
function restoreBackup(file){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!data.stores)throw new Error('Invalid backup');if(!confirm('Restore this backup? Current local records will be replaced.'))return;Object.entries(data.stores).forEach(([k,v])=>{if(Object.values(STORE).includes(k))write(k,v)});location.reload()}catch(e){toast('Could not restore: invalid backup file')}};reader.readAsText(file)}
function addStudent(existing=null){openModal(existing?'Edit student':'Register student',formGrid([field('Full name','name',existing?.name||'','text','Student full name',true),field('Student ID','id',existing?.id||'','text','e.g. MCA001',true),field('Class / Programme','studentClass',existing?.studentClass||'','text','e.g. MCA',true),field('Email address','email',existing?.email||'','email','student@example.com'),field('Phone','phone',existing?.phone||'','tel','Contact number'),field('Date of birth','dob',existing?.dob||'','date'),field('Gender','gender',existing?.gender||'','text','Gender'),field('Parent / guardian','guardian',existing?.guardian||'','text','Parent or guardian name'),field('Address','address',existing?.address||'','text','Residential address'),field('Profile photo URL','photo',existing?.photo||'','url','https://... image URL'),field('Admission date','admissionDate',existing?.admissionDate||today(),'date')]),()=>{const name=formVal('name'),id=formVal('id'),studentClass=formVal('studentClass');if(!name||!id||!studentClass){toast('Complete the required fields');return false}if(students.some(s=>String(s.id).toLowerCase()===id.toLowerCase()&&String(s.id)!==String(existing?.id))){toast('Student ID already exists');return false}const obj={...(existing||{}),id,name,studentClass,email:formVal('email'),phone:formVal('phone'),dob:formVal('dob'),gender:formVal('gender'),guardian:formVal('guardian'),address:formVal('address'),photo:formVal('photo'),admissionDate:formVal('admissionDate')||today()};if(existing){students=students.map(s=>String(s.id)===String(existing.id)?obj:s);if(String(existing.id)!==id&&accounts[existing.id]){accounts[id]=accounts[existing.id];delete accounts[existing.id]}toast('Student profile updated')}else{students.push(obj);accounts[id]=accounts[id]||{password:id};toast('Student registered. Default password is the Student ID.')}saveAll();render();return true},'STUDENT RECORD')}
function addResult(existing=null){const sOpts=students.map(s=>({value:s.id,label:`${s.name} (${s.id})`}));if(!sOpts.length){toast('Register a student first');return}openModal(existing?'Edit result':'Add exam result',formGrid([field('Student','studentId',existing?.studentId||sOpts[0].value,'text','',true,sOpts),field('Exam / Semester','exam',existing?.exam||'Semester 1','text','e.g. Semester 1',true),field('Subject','subject',existing?.subject||'','text','Subject name',true),field('Marks obtained','marks',existing?.marks??'','number','0–100',true),field('Maximum marks','maxMarks',existing?.maxMarks||100,'number','100',true),field('Exam date','examDate',existing?.examDate||today(),'date'),field('Status','status',existing?.status||'Draft','text','',true,[{value:'Draft',label:'Draft (hidden from students)'},{value:'Published',label:'Published (visible to student)'}])]),()=>{const marks=Number(formVal('marks')),max=Number(formVal('maxMarks'));if(!formVal('studentId')||!formVal('subject')||!Number.isFinite(marks)||!max||marks<0||marks>max){toast('Check student, subject, and marks');return false}const r={...(existing||{}),id:existing?.id||uid(),studentId:formVal('studentId'),exam:formVal('exam'),subject:formVal('subject'),marks,maxMarks:max,grade:gradeFor(marks,max),examDate:formVal('examDate'),status:formVal('status')};if(existing)results=results.map(x=>x.id===existing.id?r:x);else results.push(r);saveAll();toast(r.status==='Published'?'Result saved and published':'Result saved as draft');render();return true},'ACADEMIC RECORD')}
