if(a.startsWith('status-application:')){const id=a.split(':').pop(),item=applications.find(x=>x.id===id);if(!item)return;openModal('Update application status',formGrid([field('Status','status',item.status||'Applied','text','',true,[{value:'Applied',label:'Applied'},{value:'Under Review',label:'Under Review'},{value:'Shortlisted',label:'Shortlisted'},{value:'Interview',label:'Interview'},{value:'Selected',label:'Selected'},{value:'Rejected',label:'Rejected'}]),field('TPO notes','notes',item.notes||'','textarea')]),()=>{applications=applications.map(x=>x.id===id?{...x,status:formVal('status'),notes:formVal('notes')}:x);saveAll();render();toast('Application status updated');return true},'TPO · APPLICATIONS');return}
if(a==='add-interview')return addInterview();if(a.startsWith('edit-interview:'))return addInterview(interviews.find(i=>i.id===a.split(':').pop()));
if(a.startsWith('delete-interview:')){const id=a.split(':').pop();if(confirm('Delete interview?')){interviews=interviews.filter(i=>i.id!==id);saveAll();render()}return}
if(a==='add-offer')return addOffer();if(a.startsWith('status-offer:')){const id=a.split(':').pop(),item=offers.find(o=>o.id===id);if(!item)return;openModal('Update offer status',formGrid([field('Status','status',item.status||'Offered','text','',true,[{value:'Offered',label:'Offered'},{value:'Accepted',label:'Accepted'},{value:'Declined',label:'Declined'}])]),()=>{offers=offers.map(o=>o.id===id?{...o,status:formVal('status')}:o);saveAll();render();return true},'TPO · OFFERS');return}
if(a==='add-training')return addTraining();if(a.startsWith('edit-training:'))return addTraining(training.find(t=>t.id===a.split(':').pop()));
