if(a==='export-jobs')return downloadCSV('KK-Opportunities.csv',[['Role','Company','Type','Eligibility','Package','Deadline','Status'],...jobs.map(j=>[j.title,companyName(j.companyId),j.type,j.eligibility,j.package,j.deadline,j.status])]);
if(a==='export-applications')return downloadCSV('KK-Applications.csv',[['Student ID','Student','Opportunity','Company','Applied On','Status','Resume'],...applications.map(a=>[a.studentId,studentName(a.studentId),jobName(a.jobId),companyName(jobs.find(j=>j.id===a.jobId)?.companyId),a.appliedOn,a.status,a.resume||a.resumeName])]);
